import{_ as a,o as e,c as s,a3 as i}from"./chunks/framework.CVt6dz2a.js";const g=JSON.parse('{"title":"EP.16 一万栋楼与一次 draw call","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.16-instancing-lod.md","filePath":"comics/EP.16-instancing-lod.md","lastUpdated":1793881879000}'),d={name:"comics/EP.16-instancing-lod.md"};function r(n,t,l,o,h,c){return e(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="ep-16-一万栋楼与一次-draw-call" tabindex="-1">EP.16 一万栋楼与一次 draw call <a class="header-anchor" href="#ep-16-一万栋楼与一次-draw-call" aria-label="Permalink to &quot;EP.16 一万栋楼与一次 draw call&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../guide/16-large-scene/basics">16.1 基础入门：性能瓶颈认知与读数</a> 延伸阅读：<a href="./../guide/16-large-scene/advanced">进阶篇</a> · <a href="./../guide/16-large-scene/practice">实战篇</a> 动手演示：<a href="./../public/demos/large-scene/drawcall-benchmark.html">drawcall-benchmark 独立 Mesh vs InstancedMesh</a> · <a href="./../public/demos/large-scene/lod-demo.html">lod-demo LOD 距离分级</a> · <a href="./../public/demos/large-scene/city-10k.html">city-10k 万级实例城市</a></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><table tabindex="0"><thead><tr><th>格</th><th>场景</th></tr></thead><tbody><tr><td>① 困境</td><td>像素酱的 3D 城市只有 3000 栋楼，每栋楼才 12 个三角形，页面却卡成 PPT，拖动视角都顿挫。</td></tr><tr><td>② 揭秘</td><td>码叔点破：draw call 是 CPU 给 GPU&quot;打电话&quot;的次数，3000 栋楼 = 3000 次通话，16.6ms 的帧预算全花在通话费上；<code>InstancedMesh</code> 一次通话画全部。</td></tr><tr><td>③ 实证</td><td>像素酱把城市实例化：一万栋楼 draw calls 从 3000+ 降到 6，FPS 从 20 回到 60，三角形总数一栋没少。</td></tr><tr><td>④ 结案</td><td>码叔总结：先砍 draw call 再谈别的；附上坑点清单——needsUpdate 别忘、LOD 阈值别太密、巨型 InstancedMesh 要分块。</td></tr></tbody></table><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="_1-三大瓶颈来源与帧预算" tabindex="-1">① 三大瓶颈来源与帧预算 <a class="header-anchor" href="#_1-三大瓶颈来源与帧预算" aria-label="Permalink to &quot;① 三大瓶颈来源与帧预算&quot;">​</a></h3><table tabindex="0"><thead><tr><th>瓶颈</th><th>瓶颈在哪一端</th><th>直接读数</th></tr></thead><tbody><tr><td>draw call 次数</td><td>CPU → GPU 通信</td><td><code>renderer.info.render.calls</code></td></tr><tr><td>三角形总数</td><td>GPU 顶点/像素</td><td><code>renderer.info.render.triangles</code></td></tr><tr><td>纹理与显存</td><td>GPU 显存</td><td><code>renderer.info.memory.geometries / textures</code></td></tr></tbody></table><p>60fps 意味着每帧只有 <strong>16.6ms</strong> 预算，CPU 提交与 GPU 渲染合起来不能超时。3000 栋楼的场景中，几何明明很轻，帧率却崩——瓶颈是 CPU 侧的 3000 次 draw call，不是显卡。</p><h3 id="_2-instancedmesh-一次通话画全部" tabindex="-1">② InstancedMesh：一次通话画全部 <a class="header-anchor" href="#_2-instancedmesh-一次通话画全部" aria-label="Permalink to &quot;② InstancedMesh：一次通话画全部&quot;">​</a></h3><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> city</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> THREE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">InstancedMesh</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(boxGeo, mat, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">city.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setMatrixAt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(i, dummy.matrix) </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 每实例位置/旋转/缩放</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">city.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setColorAt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(i, color)         </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 每实例颜色</span></span></code></pre></div><ul><li><strong>instanceMatrix</strong>：每实例一个 4×4 矩阵，GPU 在顶点着色器里按实例序号取用；</li><li><strong>instanceColor</strong>：每实例颜色，不需要材质开 vertexColors；</li><li>draw call <strong>不随实例数增长</strong>——一万栋楼也是一次提交。</li></ul><h3 id="_3-实证数据-省的是通话费不是几何量" tabindex="-1">③ 实证数据：省的是通话费不是几何量 <a class="header-anchor" href="#_3-实证数据-省的是通话费不是几何量" aria-label="Permalink to &quot;③ 实证数据：省的是通话费不是几何量&quot;">​</a></h3><table tabindex="0"><thead><tr><th>指标</th><th>独立 Mesh ×3000</th><th>InstancedMesh ×10000</th></tr></thead><tbody><tr><td>draw calls</td><td>~3000+</td><td><strong>个位数</strong></td></tr><tr><td>FPS</td><td>~20，拖动顿挫</td><td><strong>稳定 60</strong></td></tr><tr><td>triangles</td><td>3.6 万</td><td>12 万（反而更多）</td></tr></tbody></table><p>三角形更多的实例化版本反而更流畅——因为卡顿的根源从来不是几何量，而是 CPU-GPU 通话次数。</p><h3 id="_4-配套药方-lod-与视锥剔除" tabindex="-1">④ 配套药方：LOD 与视锥剔除 <a class="header-anchor" href="#_4-配套药方-lod-与视锥剔除" aria-label="Permalink to &quot;④ 配套药方：LOD 与视锥剔除&quot;">​</a></h3><ul><li><strong>THREE.LOD</strong>：<code>addLevel(mesh, distance)</code> 按相机距离切档，远处的楼用 12 个三角形的盒子就足够；</li><li><strong>视锥剔除</strong>：默认开启，但粒度是物体级——超大 InstancedMesh 只有 1 个包围球，要按街区<strong>分块</strong>才能让视野外城区整帧跳过。</li></ul><h2 id="坑点清单-faq" tabindex="-1">坑点清单（FAQ） <a class="header-anchor" href="#坑点清单-faq" aria-label="Permalink to &quot;坑点清单（FAQ）&quot;">​</a></h2><ul><li><strong>Q：setMatrixAt 改了矩阵但画面没动？</strong> 写完矩阵必须 <code>mesh.instanceMatrix.needsUpdate = true</code>；改颜色同理，<code>instanceColor.needsUpdate = true</code>。</li><li><strong>Q：LOD 切换瞬间模型跳变明显？</strong> 加宽相邻档位的过渡距离、增加中间档，必要时做透明度淡入淡出。</li><li><strong>Q：draw call 多少算多？</strong> 经验值中端手机 &lt; 500；更可靠的判据是 Stats 的 MS 页——CPU 提交吃掉大半 16.6ms 预算就该动手了。</li><li><strong>Q：renderer.info 读数什么时候清零？</strong> 每次 <code>render()</code> 自动 reset（<code>info.autoReset</code> 默认 true）；多 pass 渲染要关 autoReset 并手动 <code>info.reset()</code>。</li></ul><h2 id="自测-quiz" tabindex="-1">自测（Quiz） <a class="header-anchor" href="#自测-quiz" aria-label="Permalink to &quot;自测（Quiz）&quot;">​</a></h2><ol><li>3000 个独立 Mesh、每个只有 12 三角形，为什么也会卡？瓶颈在 CPU 还是 GPU？</li><li>一万栋楼的 InstancedMesh 只有 1 个包围球，对视锥剔除有什么影响？怎么补救？</li><li>实例颜色改完不生效，最少需要补哪行代码？</li></ol><details><summary>答案</summary><ol><li>瓶颈在 <strong>CPU</strong>：每栋楼一次 draw call，3000 次状态准备与提交把 16.6ms 帧预算吃光。GPU 渲染的三角形总量很小，并不忙。解法：InstancedMesh 一次提交。</li><li>视锥剔除以<strong>物体</strong>为单位，1 个巨型 InstancedMesh 要么全画要么全不画，剔除基本失效。补救：按空间<strong>分块</strong>成多个 InstancedMesh（如每街区一个），并给每个块设置准确的 <code>boundingSphere</code>。</li><li><code>mesh.instanceColor.needsUpdate = true</code>（首次 <code>setColorAt</code> 后 instanceColor 缓冲才创建，改完必须标记上传）。</li></ol></details>`,21)])])}const k=a(d,[["render",r]]);export{g as __pageData,k as default};
